#include "item_pop_resources.hpp"
#include "picosha2.h"
#include <algorithm>
#include <fstream>
#include <iostream>
#include <stdexcept>

namespace ip=mh4u::item_pop_resources;
namespace {
std::size_t checks=0,boundaries=0,source_bytes=0;
void check(bool v,const char* what){++checks;if(!v)throw std::runtime_error(what);}
template<class T>const T& value(const ip::Result<T>& r){if(const auto* e=std::get_if<ip::Error>(&r))throw std::runtime_error(e->message+" at "+std::to_string(e->byte_offset));return std::get<T>(r);}
std::string read(const std::filesystem::path& p,std::size_t cap=16U<<20){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("Cannot open test input");const auto n=f.tellg();if(n<0||static_cast<std::uintmax_t>(n)>cap)throw std::runtime_error("Test input exceeds limit");std::string s(static_cast<std::size_t>(n),'\0');f.seekg(0);if(!f.read(s.data(),static_cast<std::streamsize>(s.size()))||f.peek()!=std::char_traits<char>::eof())throw std::runtime_error("Test input changed");return s;}
struct Reader {std::string data;std::size_t at{};std::string_view take(std::size_t n){if(n>data.size()-at)throw std::runtime_error("Fixture truncated");auto out=std::string_view(data).substr(at,n);at+=n;return out;}ip::Word u32(){const auto s=take(4);ip::Word v=0;for(unsigned i=0;i<4;++i)v|=ip::Word(static_cast<unsigned char>(s[i]))<<(8*i);return v;}ip::Word count(){const auto n=u32();if(n>4096)throw std::runtime_error("Fixture count exceeds limit");return n;}std::string text(){return std::string(take(count()));}};
ip::Descriptor descriptor(Reader& r){return{r.u32(),r.u32(),r.u32(),r.u32()};}
ip::Word word(std::string_view b,std::size_t o){ip::Word n=0;for(unsigned i=0;i<4;++i)n|=ip::Word(static_cast<unsigned char>(b[o+i]))<<(8*i);return n;}
void put(std::string& b,std::size_t o,ip::Word v){for(unsigned i=0;i<4;++i)b.at(o+i)=static_cast<char>(v>>(8*i));}
ip::Resource decode(const std::string& b){return value(ip::Resource::decode(b,picosha2::hash256_hex_string(b)));}
void error(const ip::Result<ip::Resource>& r,ip::ErrorCode c){++boundaries;check(std::holds_alternative<ip::Error>(r)&&std::get<ip::Error>(r).code==c,"Wrong parser error");}
std::string set_file(unsigned n){const unsigned first=8+36*n;std::string b(52+first+16,'\0');put(b,0,0x535049);put(b,4,0x2003);put(b,8,1);put(b,12,first+16);put(b,24,first);put(b,28,first);put(b,36,8);put(b,40,first+8);put(b,48,8);put(b,52,8);put(b,56,n);for(unsigned i=0;i<n;++i){const auto q=60+36*i;put(b,q,0x100);put(b,q+4,0x7fc00000+i);put(b,q+8,0xff800000);put(b,q+12,i);put(b,q+16,0x80000000);put(b,q+20,0x7f800000);put(b,q+24,0xfedc4321);put(b,q+28,0x081780ff);put(b,q+32,0xf1f2f3f4);}return b;}
std::string list_file(){std::string b(48,'\0');put(b,0,0x4c5049);put(b,4,0x2003);put(b,8,12);put(b,16,1);put(b,20,12);put(b,24,12);put(b,36,8);put(b,40,0xdeadbeef);put(b,44,0x01020304);return b;}
void parser_boundaries(const ip::Resource& real_set){
 auto s=set_file(3),l=list_file();const auto rs=decode(s),rl=decode(l);
 const auto mutate=[&](std::string src,std::size_t off,ip::Word v,ip::ErrorCode c){put(src,off,v);error(ip::Resource::decode(src,picosha2::hash256_hex_string(src)),c);};
 error(ip::Resource::decode(s,"BAD"),ip::ErrorCode::invalid_expected);error(ip::Resource::decode(s,std::string(64,'0')),ip::ErrorCode::hash_mismatch);
 mutate(s,0,0,ip::ErrorCode::unsupported_format);mutate(s,4,0x2004,ip::ErrorCode::unsupported_format);
 for(auto n:{0U,7U,51U,60U,100U}){auto short_s=s.substr(0,n);error(ip::Resource::decode(short_s,picosha2::hash256_hex_string(short_s)),ip::ErrorCode::malformed_resource);}
 mutate(s,8,0xffffffffU,ip::ErrorCode::resource_limit);mutate(s,56,0xffffffffU,ip::ErrorCode::resource_limit);mutate(s,12,1,ip::ErrorCode::malformed_resource);mutate(s,28,0,ip::ErrorCode::unsupported_format);mutate(s,52,0xfffffff0,ip::ErrorCode::malformed_resource);
 ip::Limits lim;lim.bytes=s.size()-1;error(ip::Resource::decode(s,picosha2::hash256_hex_string(s),lim),ip::ErrorCode::resource_limit);lim={};lim.loaded_bytes=1;error(ip::Resource::decode(s,picosha2::hash256_hex_string(s),lim),ip::ErrorCode::resource_limit);lim={};lim.representation_bytes=s.size()+1;error(ip::Resource::decode(s,picosha2::hash256_hex_string(s),lim),ip::ErrorCode::resource_limit);
 auto zero=set_file(0);put(zero,52,0xffffffff);const auto zero_r=decode(zero);++boundaries;check(value(zero_r.group(0)).primary.empty(),"Zero count ignores unused record pointer");
 auto gap=l;put(gap,8,100);put(gap,36,80);const auto gap_r=decode(gap);const auto member=gap_r.member(0,0);++boundaries;check(value(member)->reference.buffer_offset==80&&!value(member)->source_offset,"Opaque member in uninitialized allocation retains unknown file provenance");const auto gapbytes=gap_r.loaded_bytes(80,1);check(std::get<ip::Error>(gapbytes).code==ip::ErrorCode::uninitialized_range,"No gap zero fabrication");check(std::get<ip::Error>(gapbytes).offset_space==ip::OffsetSpace::loaded&&std::get<ip::Error>(gapbytes).byte_offset==80,"Loaded error provenance");
 auto bad=l;put(bad,36,0xffffffff);const auto bad_r=decode(bad);++boundaries;check(std::get<ip::Error>(bad_r.member(0,0)).code==ip::ErrorCode::malformed_resource,"Bad member pointer rejected on resolution");check(!value(bad_r.member(0,1)),"Out-of-table member is null before reading invalid offset");
 auto real=std::string(reinterpret_cast<const char*>(real_set.bytes().data()),real_set.bytes().size());const auto secbase=52+word(real,24);auto mismatch=real;put(mismatch,secbase+12,2);const auto mismatched=decode(mismatch);++boundaries;check(value(mismatched.group(1)).positions.size()==2&&value(mismatched.group(1)).choices.size()==3&&value(mismatched.group(1)).secondary_count==0,"Count mismatch retains independent tables and getterzero");
 mutate(real,secbase+8,0xfffffff0,ip::ErrorCode::malformed_resource);const auto nested=secbase+word(real,secbase+8);mutate(real,nested,0xfffffff0,ip::ErrorCode::malformed_resource);mutate(real,nested+4,0xffffffff,ip::ErrorCode::resource_limit);
 auto gapped=s;put(gapped,12,word(s,12)+100);put(gapped,28,word(s,28)+50);put(gapped,40,word(s,40)+50);put(gapped,52,word(s,24)+1);error(ip::Resource::decode(gapped,picosha2::hash256_hex_string(gapped)),ip::ErrorCode::uninitialized_range);
 auto preserved=std::get<ip::Resource>(ip::Resource::decode(s,picosha2::hash256_hex_string(s)));const auto borrowed=value(preserved.group(0)).primary;auto shared=preserved;preserved=rl;++boundaries;check(borrowed[2].position_bits[2]==2&&value(shared.group(0)).primary.data()==borrowed.data(),"Copy retains immutable storage and borrowed views");
 ++boundaries;check(std::get<ip::Error>(rs.members(0)).code==ip::ErrorCode::wrong_kind&&std::get<ip::Error>(rl.group(0)).code==ip::ErrorCode::wrong_kind,"Wrong kind");check(std::get<ip::Error>(rl.members(2)).code==ip::ErrorCode::index_out_of_range&&std::get<ip::Error>(rs.group(1)).code==ip::ErrorCode::index_out_of_range,"Indices bounded");
}
void run(const std::filesystem::path& fixture,std::string_view hash,const std::filesystem::path& root){Reader r{read(fixture)};check(picosha2::hash256_hex_string(r.data)==hash,"Fixture SHA mismatch");check(r.take(8)=="MH4UIP01","Fixture magic");check(r.count()==2,"Fixture resources");std::vector<ip::Resource> resources;
 for(unsigned ri=0;ri<2;++ri){const auto path=r.text(),digest=r.text();if(std::filesystem::path(path).is_absolute()||path.find("..")!=std::string::npos)throw std::runtime_error("Unsafe fixture path");const auto raw=read(root/path);const auto resource=ip::Resource::load(root/path,digest);resources.push_back(value(resource));const auto& obj=resources.back();check(obj.sha256()==digest,"Source SHA");check(static_cast<unsigned>(obj.kind())==r.u32(),"Kind");check(obj.header().size()==r.count(),"Header extent");for(auto w:obj.header())check(w==r.u32(),"Header rawbits");check(obj.segments().size()==r.count(),"Segment extent");for(auto segment:obj.segments()){check(segment.buffer_offset==r.u32()&&segment.source_offset==r.u32()&&segment.size==r.u32(),"Segment source mapping");const auto data=obj.loaded_bytes(segment.buffer_offset,segment.size);check(value(data).size()==segment.size,"Segment data extent");for(unsigned k=0;k<segment.size;++k){check(std::to_integer<unsigned char>(value(data)[k])==static_cast<unsigned char>(raw[segment.source_offset+k]),"Loaded bytes differ");++source_bytes;}}
  if(ri==0){check(obj.group_count()==r.count(),"Group count");for(unsigned g=0;g<obj.group_count();++g){const auto group=value(obj.group(g));for(auto d:group.descriptors)check(d==descriptor(r),"Group descriptor");check(group.primary.size()==r.count(),"Primary count");for(const auto& p:group.primary){check(p.source_offset==r.u32()&&p.buffer_offset==r.u32(),"Primary offsets");const auto expected=r.take(36);for(unsigned k=0;k<36;++k)check(std::to_integer<unsigned char>(p.raw[k])==static_cast<unsigned char>(expected[k]),"Primary rawbits");check(p.member_word==word(expected,0),"Primary member rawword");for(unsigned k=0;k<3;++k)check(p.position_bits[k]==word(expected,4+4*k),"Primary position raw");check(p.radius_bits==word(expected,16)&&p.height_bits==word(expected,20),"Primary dimensions raw");check(p.words18[0]==(word(expected,24)&65535)&&p.words18[1]==(word(expected,24)>>16),"Primary raw u16");for(unsigned k=0;k<8;++k)check(p.bytes1c[k]==static_cast<unsigned char>(expected[28+k]),"Primary raw bytes");}
   check(group.positions.size()==r.count(),"Position set count");for(const auto& s:group.positions){check(s.descriptor==descriptor(r),"Position descriptor");check(s.records.size()==r.count(),"Positions count");for(const auto& p:s.records){check(p.source_offset==r.u32()&&p.buffer_offset==r.u32(),"Position offsets");auto raw=r.take(28);for(unsigned k=0;k<28;++k)check(std::to_integer<unsigned char>(p.raw[k])==static_cast<unsigned char>(raw[k]),"Position raw");for(unsigned k=0;k<3;++k)check(p.position_bits[k]==word(raw,4*k),"Position typed XYZ");check(p.radius_bits==word(raw,12)&&p.height_bits==word(raw,16),"Position typed dimensions");check(p.words14[0]==(word(raw,20)&65535)&&p.words14[1]==(word(raw,20)>>16),"Position typed words");for(unsigned k=0;k<4;++k)check(p.bytes18[k]==static_cast<unsigned char>(raw[24+k]),"Position typed bytes");}}
   check(group.choices.size()==r.count(),"Choice set count");for(const auto& s:group.choices){check(s.descriptor==descriptor(r),"Choice descriptor");check(s.records.size()==r.count(),"Choices count");for(const auto& p:s.records){check(p.source_offset==r.u32()&&p.buffer_offset==r.u32(),"Choice offsets");auto raw=r.take(6);for(unsigned k=0;k<6;++k)check(std::to_integer<unsigned char>(p.raw[k])==static_cast<unsigned char>(raw[k]),"Choice raw");check(p.weight==static_cast<unsigned char>(raw[0])&&p.member==static_cast<unsigned char>(raw[1]),"Choice typed weight/member");for(unsigned k=0;k<2;++k){check(p.counts[k]==static_cast<unsigned char>(raw[2+k]),"Choice typed counts");check(p.flags[k]==static_cast<unsigned char>(raw[4+k]),"Choice typed flags");}}}
   check(group.secondary_count==(group.descriptors[1].count==group.descriptors[2].count?group.descriptors[1].count:0),"Count getter");
  }}else{for(unsigned t=0;t<2;++t){const auto table=value(obj.members(t));check(table.size()==r.count(),"IPL table count");for(unsigned i=0;i<table.size();++i){check(table[i]==descriptor(r),"IPL descriptor");const auto member=value(obj.member(t,i));check(bool(member),"IPL member exists");check(member->reference.buffer_offset==r.u32()&&member->source_offset==r.u32(),"IPL resolved offset");check(member->reference.sha256==digest,"IPL logical identity");}check(!value(obj.member(t,static_cast<ip::Word>(table.size()))),"IPL out of bound null");}}
  check(std::string_view(reinterpret_cast<const char*>(obj.bytes().data()),obj.bytes().size())==raw,"Input immutable");
 }
 check(r.at==r.data.size(),"Fixture has trailing bytes");parser_boundaries(resources[0]);
 std::cout<<"{\"status\":\"passed\",\"resources\":2,\"source_bytes\":"<<source_bytes<<",\"boundaries\":"<<boundaries<<",\"checks\":"<<checks<<"}\n";
}
}
int main(int argc,char** argv){try{if(argc!=4)throw std::runtime_error("Expected fixture SHA root");run(argv[1],argv[2],argv[3]);return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
